// 00 — CONFIGURAÇÃO CENTRAL & ALLOWLIST
const CONFIG = {
  BOT_ENABLED: true,
  CATEGORY_ID: 160,
  BOT_ALLOWED_REQUESTERS: [32598],
  INTEGRATION_USER_ID: 61622,
  FAIL_CLOSED: true,
  MAX_ACTIVE_PER_REQUESTER: 1
};

if (!CONFIG.BOT_ENABLED) {
  return [{ json: { execute: false, reason: 'KILL_SWITCH_ACTIVE' } }];
}

return [{ json: { execute: true, config: CONFIG } }];

// 02 — VALIDAÇÃO DO DEAL & ALLOWLIST DE PRODUÇÃO
const deals = $node['01_Get_New_Tickets'].json.result || [];
const config = $node['00_Load_Config'].json.config;
const validDeals = [];

for (const d of deals) {
  const requesterId = Number(d.UF_CRM_TI_REQUESTER || d.CREATED_BY_ID);
  if (Number(d.CATEGORY_ID) === config.CATEGORY_ID && config.BOT_ALLOWED_REQUESTERS.includes(requesterId)) {
    validDeals.push({
      deal_id: Number(d.ID),
      requester_id: requesterId,
      title: d.TITLE || '',
      comments: d.COMMENTS || '',
      store_id: d.UF_CRM_1689593052602,
      cat_id: d.UF_CRM_1763388156,
      subcat_id: d.UF_CRM_1763388469429
    });
    break; // Processa o chamado mais recente elegível
  }
}

return validDeals.map(d => ({ json: d }));

// 02 — PREPARAÇÃO DA SESSÃO
const deal = $node['02_Validate_Deal'].json;
const existing = $input.first().json;

let sessionStatus = 'ACTIVE';
let sessionState = 'INIT';

if (existing && existing.id) {
  // Solicitante já possui chamado ativo -> ENFILEIRA (QUEUE = PASS)
  sessionStatus = 'QUEUED';
  sessionState = 'QUEUED';
}

return [{
  json: {
    deal_id: deal.deal_id,
    requester_id: deal.requester_id,
    status: sessionStatus,
    state: sessionState,
    title: deal.title,
    comments: deal.comments,
    cat_id: deal.cat_id,
    subcat_id: deal.subcat_id,
    private_dialog_id: String(deal.requester_id)
  }
}];

// 03 — VALIDAÇÃO DE MENSAGEM RECEBIDA (DUPLICATE & SELF MESSAGE GUARD)
const rawMessages = $node['01_Get_New_Messages'].json.result?.messages || [];
const config = $node['00_Load_Config'].json.config;
const validReplies = [];

for (const m of rawMessages) {
  const authorId = Number(m.author_id);
  const msgId = String(m.id);

  // Self Message Guard (ignora mensagens emitidas pelo robô/integração)
  if (authorId === config.INTEGRATION_USER_ID) continue;

  // Allowlist Guard
  if (!config.BOT_ALLOWED_REQUESTERS.includes(authorId)) continue;

  validReplies.push({
    message_id: msgId,
    author_id: authorId,
    text: (m.text || '').trim(),
    dialog_id: String(authorId)
  });
  break;
}

return validReplies.map(r => ({ json: r }));

// 03 & 04 — NORMALIZAÇÃO DE RESPOSTAS & DUPLICATE GUARD
const session = $input.first().json;
const reply = $node['03_Validate_Message'].json;

if (!session || !session.id) {
  return [{ json: { status: 'NOOP', reason: 'NO_ACTIVE_SESSION' } }];
}

// Duplicate message guard
if (session.last_processed_message_id === reply.message_id) {
  return [{ json: { status: 'NOOP', reason: 'DUPLICATE_MESSAGE' } }];
}

const currQ = session.current_question || '';
const text = reply.text.toLowerCase();
const collData = session.collected_data_json || {};
let nextStep = 'COMPLETE_TRIAGE';

if (currQ === 'optional_comment_choice') {
  if (text.includes('sim')) {
    nextStep = 'AWAITING_OPTIONAL_COMMENT_TEXT';
  } else {
    nextStep = 'COMPLETE_TRIAGE';
  }
} else if (currQ === 'AWAITING_OPTIONAL_COMMENT_TEXT') {
  collData['optional_comment'] = reply.text;
  nextStep = 'COMPLETE_TRIAGE';
} else {
  // Normaliza resposta temática
  collData[`ANSWER_${currQ}`] = reply.text;
  nextStep = 'optional_comment_choice';
}

return [{
  json: {
    session_id: session.id,
    deal_id: session.deal_id,
    requester_id: session.requester_user_id,
    message_id: reply.message_id,
    next_step: nextStep,
    collected_data: collData,
    current_question: currQ
  }
}];

// 05 — DETECTOR CANÔNICO DE TEMA (THEME_DETECTOR)
// Ordem estrita: CATEGORY > SUBCATEGORY > COMBINATION > HIGH-CONFIDENCE TEXT > GENERIC
const deal = $input.first().json;
const catUf = String(deal.cat_id || '');

const CAT_THEMES = {
  '880': 'COMPUTADOR', '882': 'IMPRESSORA', '878': 'ERP_MICROWORK',
  '908': 'ATPV_RENAVE', '874': 'BITRIX24', '918': 'DESATIVAR_ACESSO',
  '920': 'CAMERA', '876': 'COMPRA_EQUIPAMENTO', '916': 'ACESSO_SENHA'
};

let theme = 'GENERICO';
if (CAT_THEMES[catUf]) {
  theme = CAT_THEMES[catUf];
} else {
  const norm = `${deal.title || ''} ${deal.comments || ''}`.toLowerCase();
  if (norm.includes('wifi') || norm.includes('internet') || norm.includes('rede')) theme = 'INTERNET_REDE';
  else if (norm.includes('impressora')) theme = 'IMPRESSORA';
  else if (norm.includes('computador')) theme = 'COMPUTADOR';
}

deal.theme_id = theme;
return [{ json: deal }];

// 05 — KNOWLEDGE EXTRACTOR (KNOWN DATA > ASK AGAIN)
// Invariantes estritas: DOMAIN_SCOPE != BUSINESS_IMPACT & OBSERVED_CONDITION != ROOT_CAUSE
const deal = $input.first().json;
const norm = `${deal.title || ''} ${deal.comments || ''}`.toLowerCase();
const knownData = {};
const skipped = [];

// Escopo humano somente com alta confiança
if (norm.includes('loja inteira') || norm.includes('toda a loja')) {
  knownData['IMPACT'] = 'ENTIRE_STORE';
  skipped.push('scope');
} else if (norm.includes('departamento') || norm.includes('setor inteiro')) {
  knownData['IMPACT'] = 'ENTIRE_DEPARTMENT';
  skipped.push('scope');
} else if (norm.includes('so eu') || norm.includes('so comigo')) {
  knownData['IMPACT'] = 'SINGLE_USER';
  skipped.push('scope');
}

deal.known_data = knownData;
deal.skipped_questions = skipped;
deal.next_step = deal.theme_id === 'COMPUTADOR' ? 'comp_q1_status' : 'optional_comment_choice';
return [{ json: deal }];

// 06 — QUESTION ENGINE (DYNAMIC CATALOG & COMMENT CHOICE)
const item = $input.first().json;
const nextStep = item.next_step || 'optional_comment_choice';
let text = 'Gostaria de deixar algum comentário?';

if (nextStep === 'comp_q1_status') {
  text = 'O computador liga normalmente?\n\n1. Sim\n2. Não\n3. Liga, mas apresenta erro\n4. Está muito lento';
} else if (nextStep === 'AWAITING_OPTIONAL_COMMENT_TEXT') {
  text = 'Pode escrever agora. Seja breve e envie tudo em uma única mensagem.';
} else if (nextStep === 'optional_comment_choice') {
  text = 'Gostaria de deixar algum comentário?\n\n1. Sim, quero comentar\n2. Não, pode finalizar';
}

return [{
  json: {
    deal_id: item.deal_id,
    requester_id: item.requester_id,
    dialog_id: String(item.requester_id),
    next_question_id: nextStep,
    question_text: text
  }
}];

// 10 — ERROR HANDLING & FAIL CLOSED
const errorData = $input.first().json;
return [{
  json: {
    status: 'FAIL_CLOSED',
    error_logged: true,
    action: 'NO_MESSAGE_SENT',
    details: errorData
  }
}];
